  public void Close(){opened=false;CloseDetail();CloseManage();Cancel();}
  public void Back(){if(Time.unscaledTime-lastNav<.3f)return;lastNav=Time.unscaledTime;if(ModalOpen)Cancel();else if(showManage)CloseManage();else if(showDetail)CloseDetail();else{opened=false;back?.Invoke();}}
  void OnDisable(){opened=false;if(modal!=null){Cancel();CloseDetail();CloseManage();}}
  bool Act()=>Visible&&!busy&&kind==ModalKind.None;bool Edit(){if(!Act()||Time.unscaledTime-lastEdit<.35f)return false;lastEdit=Time.unscaledTime;return true;}
  public void ChooseFilter(int slot){if(!Act())return;CloseDetail();remembered[filter]=selectedUid;filter=Mathf.Clamp(slot,-1,4);page=0;selectedUid=remembered.TryGetValue(filter,out int uid)?uid:0;Refresh(true);}
  public void SetPage(int value){if(!Act())return;page=Mathf.Clamp(value,0,Mathf.Max(0,(filtered.Count-1)/PageSize));Refresh(false);}
  public void SelectItem(int uid,bool bringIntoView=false){var g=Progress.Item(uid);if(!Valid(g)||(!Act()&&opened))return;if(bringIntoView&&filter>=0&&g.slot!=filter)filter=g.slot;selectedUid=uid;remembered[filter]=uid;Refresh(bringIntoView);}
  public void OpenDetail(){if(!Act()||!Valid(Selected))return;showDetail=true;showManage=false;Refresh();Sfx.PanelOpen();}
  public void CloseDetail(){showDetail=false;detailRoot.gameObject.SetActive(false);comparisonRoot.gameObject.SetActive(false);}
  public void OpenManage(){if(!Act()||!Valid(Selected))return;showManage=true;showDetail=false;Refresh();Sfx.PanelOpen();}
  public void CloseManage(){showManage=false;manageRoot.gameObject.SetActive(false);}
