        public void Equip(){var g=Selected;if(!Edit()||!Valid(g)||Progress.D.equipped[g.slot]==g.uid)return;Progress.Equip(g);Sfx.Toggle();Haptics.Light();Updated(true);}
        public void Upgrade(){var g=Selected;if(!Edit()||!Valid(g))return;if(Progress.LevelGear(g)){Sfx.Toggle();Haptics.Light();Updated();}else{Sfx.Deny();ShowNotice(g.level>=Progress.MaxLevel(g.rarity)?"MAX LEVEL":"NOT ENOUGH CREDITS / ALLOY");}}
        public void ToggleLock(){var g=Selected;if(!Edit()||!Valid(g))return;g.locked=!g.locked;Progress.Save();Sfx.Toggle();Updated();}
        static string Fingerprint()=>JsonUtility.ToJson(Progress.D);
        void Dialog(ModalKind type,string title,string body,int uid=0){if(!Act())return;kind=type;pendingUid=uid;pendingFingerprint=Fingerprint();modalTitle.text=title;modalBody.text=body;confirmButton.gameObject.SetActive(type!=ModalKind.Info);modal.gameObject.SetActive(true);modal.SetAsLastSibling();Sfx.PanelOpen();}
        public void RequestSalvage(){var g=Selected;if(!Act()||!Valid(g)||g.locked||Progress.D.equipped[g.slot]==g.uid)return;Dialog(ModalKind.Salvage,"SALVAGE THIS ITEM?",$"{Progress.Rarities[g.rarity]} {Progress.Slots[g.slot]}  //  LV {g.level}\n\nRecover {Meta.Salvage(g):N0} ALLOY.\nThe item will be permanently removed.",g.uid);}
        public void RequestMerge(){var g=Selected;var stack=Valid(g)&&!g.locked?Progress.MergeSet(g):null;if(!Act()||stack==null)return;Dialog(ModalKind.Merge,"MERGE THESE ITEMS?",$"Consume {stack.Count} {Progress.Rarities[g.rarity]} {Progress.Slots[g.slot]} pieces:\n"+string.Join("   ",stack.Select(x=>$"#{x.uid} LV {x.level}"))+$"\n\nCreates one {Progress.Rarities[g.rarity+1]} piece and retains the selected set / highest level."+(Progress.D.equipped[g.slot]==g.uid?"\nThe equipped item will be replaced.":""),g.uid);}
        public void RequestMergeAll(){if(!Act()||!mergeAllButton.interactable)return;Dialog(ModalKind.MergeAll,"MERGE ALL FULL STACKS?","Use the existing 3 / 3 / 4 / 5 merge rules.\n\nOnly unequipped, unlocked pieces are consumed.\nEvery complete eligible stack is merged. This cannot be undone.");}
        public void Confirm()
        {
            if(!Visible||busy||kind==ModalKind.None||kind==ModalKind.Info||Time.unscaledTime-lastEdit<.35f)return;
            if(Fingerprint()!=pendingFingerprint){Cancel();ShowNotice("INVENTORY CHANGED — REVIEW AGAIN");Refresh();return;}
            var action=kind;int uid=pendingUid;lastEdit=Time.unscaledTime;busy=true;Cancel();
            try
            {
                var g=Progress.Item(uid);
                if(action==ModalKind.Salvage&&Valid(g)&&!g.locked&&Progress.D.equipped[g.slot]!=g.uid){int a=Meta.SalvageItem(g);if(a>0){selectedUid=0;ShowNotice($"+{a:N0} ALLOY");}}
                else if(action==ModalKind.Merge&&Valid(g)&&!g.locked){var n=Progress.Merge(g);if(n!=null){selectedUid=n.uid;ShowNotice("MERGED: "+Progress.Rarities[n.rarity]+" "+Progress.Slots[n.slot]);}}
                else if(action==ModalKind.MergeAll){int n=Meta.MergeAll();ShowNotice($"{n} STACKS MERGED");}
                else if(action==ModalKind.Relic){CycleRelic();}
                Sfx.Open();Haptics.Medium();Updated();
            }
            finally{busy=false;}
        }
        public void Cancel(){kind=ModalKind.None;pendingUid=0;pendingFingerprint=null;if(modal!=null)modal.gameObject.SetActive(false);}
        public void OpenInfo(){var g=Selected;if(!Act()||!Valid(g))return;var eq=Progress.Equipped(g.slot);string set=g.set>=0&&g.set<Meta.Sets.Length?$"\n\n{Meta.Sets[g.set]} SET: {Meta.SetPieces(g.set)} EQUIPPED\n2 PIECES: {Meta.Set2[g.set]}\n4 PIECES: {Meta.Set4[g.set]}":"\n\nNO SET";Dialog(ModalKind.Info,Progress.Rarities[g.rarity]+" "+Progress.Slots[g.slot],$"SELECTED: LV {g.level}/{Progress.MaxLevel(g.rarity)}   {Progress.StatText(g)}\n"+(string.IsNullOrEmpty(Meta.Affixes(g))?"NO RARITY AFFIXES":Meta.Affixes(g))+set+"\n\nACTUALLY EQUIPPED: "+(eq==null?"EMPTY":$"{Progress.Rarities[eq.rarity]} LV {eq.level}  {Progress.StatText(eq)}")+"\nTOTAL POWER USES EQUIPPED GEAR ONLY.",g.uid);}
        public void OpenRelics(){if(!Act())return;if(!Meta.RelicSlotOpen){ShowNotice("RELIC SLOT OPENS AT 60 STARS");return;}int ri=Meta.EquippedRelic;Dialog(ModalKind.Relic,"RELIC",(ri<0?"NONE EQUIPPED":Meta.Relics[ri]+$"  LV {Meta.RelicLv(ri)}/5\n"+Meta.RelicDesc(ri))+$"\n\n{Meta.RelicsOwned} RELICS OWNED.\nCONFIRM: CYCLE TO NEXT OWNED RELIC / NONE.\n"+(ri<0?"":$"UPGRADE: {Meta.RelicCost(ri):N0} ALLOY (MAX LEVEL 5).\n"));ShowRelicUpgrade();}
        void CycleRelic(){if(!Meta.RelicSlotOpen)return;int cur=Progress.D.equippedRelic,n=Meta.Relics.Length;for(int k=1;k<=n+1;k++){int i=(cur+1+k)%(n+1)-1;if(i<0||Meta.RelicLv(i)>0){Progress.D.equippedRelic=i;break;}}Progress.Save();}
        void ShowRelicUpgrade(){var old=modal.Find("RelicUpgrade");if(old!=null)old.gameObject.SetActive(true);else{var b=Hit(modal,"RelicUpgrade",1040,806,270,112,UpgradeRelic);BlueUi.Image(b.transform,"Face","button_blue_blank",0,0,270,112,true);T(b.transform,"Label",15,0,240,62,28,Ice).text="UPGRADE RELIC";}var button=modal.Find("RelicUpgrade").GetComponent<UnityEngine.UI.Button>();int ri=Meta.EquippedRelic;button.interactable=ri>=0&&Meta.RelicCost(ri)>0&&Progress.D.alloy>=Meta.RelicCost(ri);}
        void UpgradeRelic(){if(!Visible||kind!=ModalKind.Relic||Time.unscaledTime-lastEdit<.35f)return;int ri=Meta.EquippedRelic;if(ri<0||!Meta.RelicSlotOpen)return;lastEdit=Time.unscaledTime;if(Meta.LevelRelic(ri)){Cancel();Updated();ShowNotice("RELIC UPGRADED");}else{Sfx.Deny();ShowNotice("MAX LEVEL / NOT ENOUGH ALLOY");}}
        public void ShowNotice(string value){notice.text=value.ToUpperInvariant();noticeUntil=Time.unscaledTime+2.8f;}

